import React, { useState } from 'react';
import {
  AppBar,
  Toolbar,
  Typography,
  IconButton,
  Badge,
  Button,
  Box,
  InputBase,
  Menu,
  MenuItem,
  Avatar,
  Divider,
  Chip,
} from '@mui/material';
import { styled, alpha } from '@mui/material/styles';
import {
  ShoppingCart as CartIcon,
  Search as SearchIcon,
  Menu as MenuIcon,
  Person as PersonIcon,
  Notifications as NotificationIcon,
  Store as StoreIcon,
} from '@mui/icons-material';
import { useNavigate, Link } from 'react-router-dom';
import { useCart } from '../../context/CartContext';
// import { useSocket } from '../../hooks/useSocket';

// Styled components
const Search = styled('div')(({ theme }) => ({
  position: 'relative',
  borderRadius: theme.shape.borderRadius,
  backgroundColor: alpha(theme.palette.common.white, 0.15),
  '&:hover': {
    backgroundColor: alpha(theme.palette.common.white, 0.25),
  },
  marginLeft: 0,
  width: '100%',
  [theme.breakpoints.up('sm')]: {
    marginLeft: theme.spacing(1),
    width: 'auto',
  },
}));

const SearchIconWrapper = styled('div')(({ theme }) => ({
  padding: theme.spacing(0, 2),
  height: '100%',
  position: 'absolute',
  pointerEvents: 'none',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
}));

const StyledInputBase = styled(InputBase)(({ theme }) => ({
  color: 'inherit',
  '& .MuiInputBase-input': {
    padding: theme.spacing(1, 1, 1, 0),
    paddingLeft: `calc(1em + ${theme.spacing(4)})`,
    transition: theme.transitions.create('width'),
    width: '100%',
    [theme.breakpoints.up('sm')]: {
      width: '20ch',
      '&:focus': {
        width: '30ch',
      },
    },
  },
}));

const Navbar = () => {
  const navigate = useNavigate();
  const { getCartCount } = useCart();
  // const { isConnected } = useSocket();
  const isConnected = true; // Demo mode
  
  const [searchValue, setSearchValue] = useState('');
  const [userMenuAnchor, setUserMenuAnchor] = useState(null);
  const [notificationAnchor, setNotificationAnchor] = useState(null);

  // Handle search
  const handleSearch = (e) => {
    e.preventDefault();
    if (searchValue.trim()) {
      navigate(`/products?search=${encodeURIComponent(searchValue.trim())}`);
      setSearchValue('');
    }
  };

  // Handle user menu
  const handleUserMenuOpen = (event) => {
    setUserMenuAnchor(event.currentTarget);
  };

  const handleUserMenuClose = () => {
    setUserMenuAnchor(null);
  };

  // Handle notification menu
  const handleNotificationOpen = (event) => {
    setNotificationAnchor(event.currentTarget);
  };

  const handleNotificationClose = () => {
    setNotificationAnchor(null);
  };

  // Navigation items
  const navigationItems = [
    { label: 'Home', path: '/' },
    { label: 'Products', path: '/products' },
    { label: 'Categories', path: '/products?category=shirts' },
    { label: 'Sale', path: '/products?sale=true' },
  ];

  return (
    <AppBar position="sticky" elevation={1}>
      <Toolbar sx={{ px: { xs: 1, sm: 2 } }}>
        {/* Logo */}
        <Box 
          component={Link} 
          to="/" 
          sx={{ 
            display: 'flex', 
            alignItems: 'center', 
            textDecoration: 'none', 
            color: 'inherit',
            mr: 3
          }}
        >
          <StoreIcon sx={{ mr: 1 }} />
          <Typography
            variant="h6"
            noWrap
            sx={{
              fontWeight: 700,
              letterSpacing: '0.1rem',
            }}
          >
            ClothStore
          </Typography>
        </Box>

        {/* Navigation Links - Desktop */}
        <Box sx={{ display: { xs: 'none', md: 'flex' }, mr: 2 }}>
          {navigationItems.map((item) => (
            <Button
              key={item.label}
              color="inherit"
              component={Link}
              to={item.path}
              sx={{ mx: 1, textTransform: 'none' }}
            >
              {item.label}
            </Button>
          ))}
        </Box>

        {/* Search Bar */}
        <Search sx={{ flexGrow: 1, maxWidth: 400 }}>
          <SearchIconWrapper>
            <SearchIcon />
          </SearchIconWrapper>
          <form onSubmit={handleSearch}>
            <StyledInputBase
              placeholder="Search products..."
              value={searchValue}
              onChange={(e) => setSearchValue(e.target.value)}
              inputProps={{ 'aria-label': 'search' }}
            />
          </form>
        </Search>

        <Box sx={{ flexGrow: 1 }} />

        {/* Right side icons */}
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          {/* Connection Status */}
          <Chip
            size="small"
            label={isConnected ? 'Live' : 'Offline'}
            color={isConnected ? 'success' : 'error'}
            variant="outlined"
            sx={{ 
              display: { xs: 'none', sm: 'flex' },
              fontSize: '0.75rem',
              height: 24
            }}
          />

          {/* Notifications */}
          <IconButton
            color="inherit"
            onClick={handleNotificationOpen}
            aria-label="notifications"
          >
            <Badge badgeContent={0} color="error">
              <NotificationIcon />
            </Badge>
          </IconButton>

          {/* Cart */}
          <IconButton
            color="inherit"
            component={Link}
            to="/cart"
            aria-label="shopping cart"
          >
            <Badge 
              badgeContent={cartSummary.itemCount} 
              color="error"
              max={99}
            >
              <CartIcon />
            </Badge>
          </IconButton>

          {/* User Menu */}
          <IconButton
            color="inherit"
            onClick={handleUserMenuOpen}
            aria-label="user menu"
          >
            <PersonIcon />
          </IconButton>

          {/* Mobile Menu */}
          <IconButton
            color="inherit"
            aria-label="menu"
            sx={{ display: { md: 'none' } }}
          >
            <MenuIcon />
          </IconButton>
        </Box>

        {/* User Menu */}
        <Menu
          anchorEl={userMenuAnchor}
          open={Boolean(userMenuAnchor)}
          onClose={handleUserMenuClose}
          onClick={handleUserMenuClose}
          transformOrigin={{ horizontal: 'right', vertical: 'top' }}
          anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
        >
          <MenuItem onClick={() => navigate('/orders')}>
            My Orders
          </MenuItem>
          <MenuItem onClick={() => navigate('/profile')}>
            Profile
          </MenuItem>
          <MenuItem onClick={() => navigate('/settings')}>
            Settings
          </MenuItem>
          <Divider />
          <MenuItem>
            Login
          </MenuItem>
        </Menu>

        {/* Notification Menu */}
        <Menu
          anchorEl={notificationAnchor}
          open={Boolean(notificationAnchor)}
          onClose={handleNotificationClose}
          onClick={handleNotificationClose}
          transformOrigin={{ horizontal: 'right', vertical: 'top' }}
          anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
        >
          <MenuItem>
            <Typography variant="body2" color="text.secondary">
              No new notifications
            </Typography>
          </MenuItem>
        </Menu>
      </Toolbar>

      {/* Mobile Navigation - could be expanded to a drawer */}
    </AppBar>
  );
};

export default Navbar;
